sys_variable_value.value:
(function execute(inputs, outputs) {
    var fieldList = [];
    var gr = inputs.record;

    // 1. Define the fields you want to skip
    var excludeList = ['u_invoice', 'u_invoiced', 'invoice', 'invoiced', 'sys_id', 'u_ai_processed'];

    // 2. Define your hardcoded fields to always include (if they have data)
    var hardcodedFields = ['description', 'quantity', 'price_per_unit', 'total'];

    if (gr && gr.isValidRecord()) {
        var fields = gr.getElements();
        
        for (var i = 0; i < fields.length; i++) {
            var field = fields[i];
            var name = field.getName();

            var isTargetField = name.startsWith('u_') || hardcodedFields.indexOf(name) !== -1;

            if (isTargetField && !field.nil() && excludeList.indexOf(name) === -1) {
                fieldList.push(name);
            }
        }
    }

    outputs.field_list = fieldList;

})(inputs, outputs);

